INSERT INTO chapter_content (chapter_slug, subject_id, chapter_number, title, answers_json) VALUES ('telangana-economy-en-ch3-macro-economic-trends', 'telangana-economy-en', 3, 'Macro Economics', '[{"a":"Rs.17,82,198 crore","e":"This represents a growth rate of 10.7% over 2024-25 (FRE), significantly higher than the All India growth rate of 8.0% for the same period. See table below for the full current/constant price comparison.","table":{"headers":["Description","2024-25 (Current, Rs. cr)","2025-26 (Current, Rs. cr)","GR% Current","2024-25 (Constant, Rs. cr)","2025-26 (Constant, Rs. cr)","GR% Constant"],"rows":[["Telangana","16,09,902","17,82,198","10.7","8,20,197","8,89,582","8.5"],["All India","3,30,68,145","3,57,13,886","8.0","1,87,96,955","2,01,89,919","7.4"]]},"type":"mcq","options":{"a":"Rs.8,89,582 crore","b":"Rs.17,82,198 crore","c":"Rs.18,21,340 crore","d":"Rs.16,09,902 crore"},"answer":"b"},{"a":"8.5%","e":"","table":null,"type":"mcq","options":{"a":"10.7%","b":"8.5%","c":"7.4%","d":"8.0%"},"answer":"b"},{"a":"4.99%","e":"","table":null,"type":"mcq","options":{"a":"4.99%","b":"5.24%","c":"5.10%","d":"4.92%"},"answer":"a"},{"a":"Rs.4,18,931","e":"This is nearly double the national average PCI of Rs.2,19,575 for the same year, reflecting a growth rate of 10.2%. See table below for the full current/constant price comparison.","table":{"headers":["Description","2024-25 (Current, Rs.)","2025-26 (Current, Rs.)","GR% Current","2024-25 (Constant, Rs.)","2025-26 (Constant, Rs.)","GR% Constant"],"rows":[["Telangana","3,80,031","4,18,931","10.2","1,88,436","2,04,022","8.3"],["All India","2,05,324","2,19,575","6.9","1,14,710","1,21,968","6.3"]]},"type":"mcq","options":{"a":"Rs.4,18,931","b":"Rs.2,19,575","c":"Rs.3,80,031","d":"Rs.4,76,679"},"answer":"a"},{"a":"8.3%","e":"","table":null,"type":"mcq","options":{"a":"6.3%","b":"8.3%","c":"10.2%","d":"5.5%"},"answer":"b"},{"a":"6.9%","e":"","table":null,"type":"mcq","options":{"a":"6.3%","b":"8.7%","c":"6.9%","d":"5.4%"},"answer":"c"},{"a":"2047","e":"The vision also sets an interim milestone of USD 1 trillion by 2034, and aims to raise Telangana''s share in India''s GDP from 5% to 10%.","table":null,"type":"mcq","options":{"a":"2047","b":"2041","c":"2034","d":"2050"},"answer":"a"},{"a":"7%","e":"The growth path envisages 8% (2025-30), 7% (2031-39), and 5.2% (2041-47). See table below.","table":{"headers":["Period","Forecast Average Real GDP Growth"],"rows":[["2025-30","8%"],["2031-39","7%"],["2041-47","5.2%"]]},"type":"mcq","options":{"a":"7%","b":"10.7%","c":"5.2%","d":"8%"},"answer":"a"},{"a":"A spatial planning model dividing the State into sector-specific economic zones","e":"","table":null,"type":"mcq","options":{"a":"A taxation reform framework","b":"A labour welfare scheme","c":"A spatial planning model dividing the State into sector-specific economic zones","d":"A banking regulation framework"},"answer":"c"},{"a":"7.4%","e":"","table":null,"type":"mcq","options":{"a":"7.4%","b":"8.0%","c":"6.4%","d":"7.3%"},"answer":"a"},{"a":"Tertiary","e":"Tertiary sector contributes 68.6% to Telangana''s GSVA, much higher than the national share of 56.4%. See table below for the full broad sector contribution comparison.","table":{"headers":["Sector","Telangana (%)","All India (%)"],"rows":[["Primary","15.1","18.4"],["Secondary","16.3","25.2"],["Tertiary","68.6","56.4"]]},"type":"mcq","options":{"a":"Tertiary","b":"Secondary","c":"Public Administration","d":"Primary"},"answer":"a"},{"a":"13.5%","e":"This was the highest among the three sectors and exceeded the All India tertiary growth rate of 10.6%. See table below for all three sectors'' growth comparison.","table":{"headers":["Sector","Telangana (%)","All India (%)"],"rows":[["Primary","1.4","0.2"],["Secondary","9.4","7.5"],["Tertiary","13.5","10.6"]]},"type":"mcq","options":{"a":"14.1%","b":"13.5%","c":"10.6%","d":"9.4%"},"answer":"b"},{"a":"Rs.2,49,691 crore","e":"This reflects a growth rate of 1.4% over 2024-25 (FRE), attributed to enhanced area, agricultural productivity, and allied activities like livestock and fisheries.","table":null,"type":"mcq","options":{"a":"Rs.11,30,596 crore","b":"Rs.2,49,691 crore","c":"Rs.2,46,282 crore","d":"Rs.2,68,325 crore"},"answer":"b"},{"a":"Livestock","e":"Livestock leads at 41.4%, closely followed by crops. See table below for the full sub-sector composition.","table":{"headers":["Sub-sector","Contribution (%)"],"rows":[["Livestock","41.4"],["Crops","38.2"],["Mining & Quarrying","14.4"],["Fishing & Aquaculture","3.1"],["Forestry & Logging","2.9"]]},"type":"mcq","options":{"a":"Mining & Quarrying","b":"Fishing & Aquaculture","c":"Livestock","d":"Crops"},"answer":"c"},{"a":"Rs.2,68,325 crore","e":"This registered a growth rate of 9.4%, higher than the All India secondary sector growth rate of 7.5%.","table":null,"type":"mcq","options":{"a":"Rs.2,49,691 crore","b":"Rs.2,68,325 crore","c":"Rs.11,30,596 crore","d":"Rs.81,71,692 crore"},"answer":"b"},{"a":"Manufacturing","e":"Manufacturing accounts for 51.1%, followed by Construction. See table below for the full sub-sector composition.","table":{"headers":["Sub-sector","Contribution (%)"],"rows":[["Manufacturing","51.1"],["Construction","34.8"],["Electricity, Gas, Water Supply & Other Utility Services","14.1"]]},"type":"mcq","options":{"a":"Mining","b":"Manufacturing","c":"Electricity, Gas, Water Supply & Other Utility Services","d":"Construction"},"answer":"b"},{"a":"Rs.11,30,596 crore","e":"This registered a growth rate of 13.5%, making it the main driver of Telangana''s economy.","table":null,"type":"mcq","options":{"a":"Rs.11,30,596 crore","b":"Rs.17,82,198 crore","c":"Rs.1,82,39,719 crore","d":"Rs.2,68,325 crore"},"answer":"a"},{"a":"Real Estate, Ownership of Dwelling and Professional Services","e":"This sub-sector contributes 34.1%, followed by Trade, Repair, Hotels and Restaurants at 30.4%. See table below for the full sub-sector composition.","table":{"headers":["Sub-sector","Contribution (%)"],"rows":[["Real Estate, Ownership of Dwelling and Professional Services","34.1"],["Trade, Repair, Hotels and Restaurants","30.4"],["Transport, Storage, Communication & Broadcasting","12.2"],["Other Services","12.5"],["Financial Services","7.3"],["Public Administration","3.5"]]},"type":"mcq","options":{"a":"Real Estate, Ownership of Dwelling and Professional Services","b":"Financial Services","c":"Trade, Repair, Hotels and Restaurants","d":"Transport, Storage, Communication & Broadcasting"},"answer":"a"},{"a":"7%","e":"This makes Telangana the fourth-largest Generative AI startup hub in the country, after Karnataka, Maharashtra, and Delhi.","table":null,"type":"mcq","options":{"a":"40%","b":"10%","c":"7%","d":"5%"},"answer":"c"},{"a":"5","e":"","table":null,"type":"mcq","options":{"a":"3","b":"5","c":"7","d":"10"},"answer":"b"},{"a":"Karnataka, Maharashtra, Tamil Nadu","e":"","table":null,"type":"mcq","options":{"a":"Karnataka, Maharashtra, Tamil Nadu","b":"Maharashtra, Uttar Pradesh, Punjab","c":"Tamil Nadu, Kerala, Gujarat","d":"Karnataka, Gujarat, Kerala"},"answer":"a"},{"a":"Rangareddy","e":"Rangareddy topped with a GDDP of Rs.3,41,080 crore, followed by Hyderabad (Rs.2,25,860 crore) and Medchal-Malkajgiri (Rs.1,16,133 crore). See table below for the top districts by GDDP.","table":{"headers":["District","GDDP (Rs. crore)","Rank"],"rows":[["Rangareddy","3,41,080","1"],["Hyderabad","2,25,860","2"],["Medchal-Malkajgiri","1,16,133","3"],["Sangareddy","74,194","4"],["Nalgonda","64,219","5"]]},"type":"mcq","options":{"a":"Hyderabad","b":"Sangareddy","c":"Medchal-Malkajgiri","d":"Rangareddy"},"answer":"d"},{"a":"Mulugu","e":"Mulugu ranked last (33rd) with a GDDP of Rs.11,943 crore, reflecting limited industrialization and higher forest cover.","table":null,"type":"mcq","options":{"a":"Kumuram Bheem","b":"Rajanna Siricilla","c":"Mulugu","d":"Jayashankar"},"answer":"c"},{"a":"Rangareddy","e":"Rangareddy recorded a PCI of Rs.11,29,735, attributed to concentration of IT parks, industrial estates, logistics hubs, and proximity to Hyderabad. See table below for the top districts by PCI.","table":{"headers":["District","PCI (Rs.)","Rank"],"rows":[["Rangareddy","11,29,735","1"],["Hyderabad","4,76,679","2"],["Sangareddy","3,94,587","3"],["Medchal-Malkajgiri","3,81,506","4"],["Bhadradri Kothagudem","3,69,420","5"]]},"type":"mcq","options":{"a":"Sangareddy","b":"Medchal-Malkajgiri","c":"Hyderabad","d":"Rangareddy"},"answer":"d"},{"a":"Hanumakonda","e":"Hanumakonda ranked last (33rd) with a PCI of Rs.2,37,809, attributed to a smaller industrial base and greater reliance on agriculture.","table":null,"type":"mcq","options":{"a":"Hanumakonda","b":"Vikarabad","c":"Jagtial","d":"Rajanna Siricilla"},"answer":"a"},{"a":"10%","e":"","table":null,"type":"mcq","options":{"a":"10%","b":"15%","c":"8%","d":"12%"},"answer":"a"},{"a":"USD 1.21 trillion","e":"Achieving the aspirational USD 3 trillion target requires accelerated growth through higher investment, productivity enhancement, structural transformation, and sustained human capital development.","table":null,"type":"mcq","options":{"a":"USD 3 trillion","b":"USD 2 trillion","c":"USD 1.21 trillion","d":"USD 1 trillion"},"answer":"c"},{"a":"Services","e":"The services sector is targeted to reach USD 1.95 trillion, supported by high-value services and global investment ecosystems. See table below for the full sectoral breakdown.","table":{"headers":["Sector","Target by 2047"],"rows":[["Agriculture","USD 0.33 trillion"],["Industry","USD 0.5 trillion"],["Services","USD 1.95 trillion"],["Taxes and Subsidies","USD 0.22 trillion"]]},"type":"mcq","options":{"a":"Industry","b":"Taxes and Subsidies","c":"Agriculture","d":"Services"},"answer":"d"},{"a":"2011-12","e":"","table":null,"type":"mcq","options":{"a":"2022-23","b":"2011-12","c":"2004-05","d":"2017-18"},"answer":"b"},{"a":"2022-23","e":"","table":null,"type":"mcq","options":{"a":"2017-18","b":"2020-21","c":"2022-23","d":"2025-26"},"answer":"c"},{"a":"27th February, 2026","e":"The corresponding State estimates of GSDP for the new series are to be released in April 2026.","table":null,"type":"mcq","options":{"a":"27th March, 2026","b":"27th January, 2026","c":"27th April, 2026","d":"27th February, 2026"},"answer":"d"},{"a":"3.7%","e":"This was lower than the All India average of 4.6%. See table below for the year-on-year comparison.","table":{"headers":["Period","Telangana (%)","All India (%)"],"rows":[["2024-25 (Annual)","3.7","4.6"],["2025-26 (Apr-Dec)","0.2","1.7"]]},"type":"mcq","options":{"a":"0.2%","b":"4.6%","c":"3.7%","d":"1.7%"},"answer":"c"},{"a":"0.2%","e":"This was significantly lower than the All India average of 1.7%, reflecting strong price stability due to lower food prices and effective supply-side conditions.","table":null,"type":"mcq","options":{"a":"0.2%","b":"1.7%","c":"3.7%","d":"4.6%"},"answer":"a"},{"a":"6.1%","e":"","table":null,"type":"mcq","options":{"a":"6.1%","b":"8.5%","c":"4.9%","d":"7.3%"},"answer":"a"},{"a":"60.7%","e":"This is significantly higher than the All India average of 55.8%. See table below for the rural-urban breakdown.","table":{"headers":["Category","Telangana (%)","All India (%)"],"rows":[["Rural","66.1","58.4"],["Urban","53.3","50.4"],["Overall","60.7","55.8"]]},"type":"mcq","options":{"a":"57.0%","b":"60.7%","c":"55.8%","d":"66.1%"},"answer":"b"},{"a":"45.4%","e":"This is 10.5 percentage points higher than the national average of 34.9%.","table":null,"type":"mcq","options":{"a":"39.4%","b":"45.4%","c":"55.1%","d":"32.0%"},"answer":"b"},{"a":"55.1%","e":"This is significantly higher than the All India rural female LFPR of 39.4%. See table below for the full gender × rural-urban breakdown.","table":{"headers":["Category","Telangana Male (%)","Telangana Female (%)","All India Male (%)","All India Female (%)"],"rows":[["Rural","77.9","55.1","78.8","39.4"],["Urban","76.2","32.0","75.1","25.5"]]},"type":"mcq","options":{"a":"39.4%","b":"32.0%","c":"45.4%","d":"55.1%"},"answer":"d"},{"a":"Telangana","e":"Telangana recorded a combined LFPR of 60.7%, the highest among southern States. See table below for the full comparison.","table":{"headers":["State","Rural (%)","Urban (%)","Combined (%)"],"rows":[["Telangana","66.1","53.3","60.7"],["Andhra Pradesh","61.0","50.5","57.2"],["Karnataka","62.7","51.8","58.2"],["Kerala","54.0","49.1","51.6"],["Tamil Nadu","65.1","54.5","59.8"]]},"type":"mcq","options":{"a":"Andhra Pradesh","b":"Tamil Nadu","c":"Karnataka","d":"Telangana"},"answer":"d"},{"a":"57.0%","e":"This is higher than the All India WPR of 53.1%. See table below for the rural-urban breakdown.","table":{"headers":["Category","Telangana (%)","All India (%)"],"rows":[["Rural","62.5","56.1"],["Urban","49.5","47.1"],["Overall","57.0","53.1"]]},"type":"mcq","options":{"a":"55.8%","b":"53.1%","c":"60.7%","d":"57.0%"},"answer":"d"},{"a":"52.4%","e":"This is significantly higher than the All India rural female WPR of 37.9%. See table below for the full gender × rural-urban breakdown.","table":{"headers":["Category","Telangana Male (%)","Telangana Female (%)","All India Male (%)","All India Female (%)"],"rows":[["Rural","73.3","52.4","75.5","37.9"],["Urban","71.2","29.4","70.7","23.2"]]},"type":"mcq","options":{"a":"52.4%","b":"29.4%","c":"37.9%","d":"23.2%"},"answer":"a"},{"a":"Telangana","e":"Telangana recorded a combined WPR of 57.0%, the highest among southern States. See table below for the full comparison.","table":{"headers":["State","Rural (%)","Urban (%)","Combined (%)"],"rows":[["Telangana","62.5","49.5","57.0"],["Andhra Pradesh","57.7","46.6","53.7"],["Karnataka","61.3","50.1","56.6"],["Kerala","50.0","45.3","47.6"],["Tamil Nadu","61.5","51.1","56.3"]]},"type":"mcq","options":{"a":"Telangana","b":"Karnataka","c":"Andhra Pradesh","d":"Tamil Nadu"},"answer":"a"},{"a":"36.3%","e":"This is higher than the All India average of 32.8%. See table below for the full sector-wise employment comparison.","table":{"headers":["Sector","Telangana (%)","All India (%)"],"rows":[["Agriculture","41.5","43.2"],["Industries","22.2","24.0"],["Services","36.3","32.8"]]},"type":"mcq","options":{"a":"36.3%","b":"32.8%","c":"22.2%","d":"41.5%"},"answer":"a"},{"a":"62.6%","e":"This compares with 58.5% in All India rural areas. See table below for the full rural-urban sector-wise breakdown.","table":{"headers":["Sector","Telangana Rural (%)","Telangana Urban (%)","All India Rural (%)","All India Urban (%)"],"rows":[["Agriculture","62.6","4.9","58.5","6.7"],["Industries","17.7","30.2","20.9","31.5"],["Services","19.7","64.9","20.6","61.9"]]},"type":"mcq","options":{"a":"62.6%","b":"19.7%","c":"58.5%","d":"4.9%"},"answer":"a"},{"a":"5%","e":"Telangana ranks among the top seven states — alongside Tamil Nadu, Gujarat, Maharashtra, Uttar Pradesh, Karnataka, and Haryana — that collectively contribute 60% of the country''s total manufacturing employment.","table":null,"type":"mcq","options":{"a":"10%","b":"3%","c":"7%","d":"5%"},"answer":"d"},{"a":"PURE (Peri-Urban Region)","e":"CURE strengthens Hyderabad as a hub for technology, DeepTech, AI, and Industry 4.0; RARE focuses on rural incomes through agriculture, livestock, fisheries, handlooms, and eco-tourism.","table":null,"type":"mcq","options":{"a":"PURE (Peri-Urban Region)","b":"CURE (Core Urban Region)","c":"None of the above","d":"RARE (Rural Agriculture Region)"},"answer":"a"},{"a":"3.3%","e":"Global growth is projected to hold at 3.3% in 2026 before easing to 3.2% in 2027, a slight upward revision of 0.2 percentage points for 2026 from the October 2025 forecast.","table":null,"type":"mcq","options":{"a":"3.4%","b":"3.2%","c":"4.1%","d":"3.3%"},"answer":"d"},{"a":"United States of America","e":"Advanced economies overall are projected to grow at 1.8% in 2026.","table":null,"type":"mcq","options":{"a":"United States of America","b":"Germany","c":"Japan","d":"United Kingdom"},"answer":"a"},{"a":"6.4%","e":"India led EMDE with 7.3% projected for 2025, outpacing the EMDE average of 4.2%. China follows at 5.0% (2025) and 4.5% (2026).","table":null,"type":"mcq","options":{"a":"4.5%","b":"6.4%","c":"4.2%","d":"7.3%"},"answer":"b"},{"a":"All of the above","e":"These expanded administrative, survey, and digital data sources are intended to make economic measurement more realistic and up to date.","table":null,"type":"mcq","options":{"a":"All of the above","b":"I only","c":"I and II only","d":"II and III only"},"answer":"a"},{"a":"Computer Assisted Personal Interviews (CAPI)","e":"Along with CAPI, MoSPI is also leveraging AI, Machine Learning, and Natural Language Processing (NLP) for rigorous data validation and reliable index generation.","table":null,"type":"mcq","options":{"a":"Computer Assisted Personal Interviews (CAPI)","b":"Biometric authentication","c":"Satellite imaging","d":"Blockchain-based ledgers"},"answer":"a"},{"a":"3.8%","e":"Global inflation is expected to decline gradually from 4.1% in 2025 to 3.8% in 2026 and 3.4% in 2027, mainly due to lower global demand and falling energy prices.","table":null,"type":"mcq","options":{"a":"4.6%","b":"3.8%","c":"4.1%","d":"3.4%"},"answer":"b"},{"a":"October 2025","e":"This decline was mainly due to lower food prices supported by good agricultural output; India''s retail inflation averaged 1.7% during April-December 2025-26.","table":null,"type":"mcq","options":{"a":"July 2025","b":"December 2025","c":"October 2025","d":"April 2025"},"answer":"c"},{"a":"Telangana Shops and Establishments Act","e":"This labour reform, highlighted in the Economic Survey 2025-26, is expected to strengthen female labour force participation and support sustained industrial growth, subject to safety provisions.","table":null,"type":"mcq","options":{"a":"Telangana Factories Act","b":"Telangana Labour Welfare Act","c":"Telangana Industrial Policy Act","d":"Telangana Shops and Establishments Act"},"answer":"d"}]') ON CONFLICT(chapter_slug) DO UPDATE SET subject_id=excluded.subject_id, chapter_number=excluded.chapter_numbe